  "verbo-16": {"promptNative": "Tu ___ (partir = partire) domani mattina.", "explain": "La forma tu di 'partir' (futuro) è 'partiras'.", "wrongNote": "Esercizio di coniugazione: questa frase richiede il futuro semplice (forma tu (tu)) di partir, che è \"partiras\" — \"demain\" (domani) indica il futuro.", "distractorNotes": {"partirai": "\"partirai\" è la forma je del futuro semplice di partir, ma qui il soggetto è tu (tu) — persona sbagliata.", "partirons": "\"partirons\" è la forma nous del futuro semplice di partir, ma qui il soggetto è tu (tu) — persona sbagliata.", "partira": "\"partira\" è la forma il/elle/on del futuro semplice di partir, ma qui il soggetto è tu (tu) — persona sbagliata."}},
  "verbo-17": {"promptNative": "Lui ___ (partir = partire) domani mattina.", "explain": "La forma lui/lei di 'partir' (futuro) è 'partira'.", "wrongNote": "Esercizio di coniugazione: questa frase richiede il futuro semplice (forma il/elle/on (lui/lei/uno)) di partir, che è \"partira\" — \"demain\" (domani) indica il futuro.", "distractorNotes": {"partirez": "\"partirez\" è la forma vous del futuro semplice di partir, ma qui il soggetto è il/elle/on (lui/lei/si) — persona sbagliata.", "partiras": "\"partiras\" è la forma tu del futuro semplice di partir, ma qui il soggetto è il/elle/on (lui/lei/si) — persona sbagliata.", "partirai": "\"partirai\" è la forma je del futuro semplice di partir, ma qui il soggetto è il/elle/on (lui/lei/si) — persona sbagliata."}},
  "verbo-18": {"promptNative": "Noi ___ (partir = partire) domani mattina.", "explain": "La forma noi di 'partir' (futuro) è 'partirons'.", "wrongNote": "Esercizio di coniugazione: questa frase richiede il futuro semplice (forma nous (noi)) di partir, che è \"partirons\" — \"demain\" (domani) indica il futuro.", "distractorNotes": {"partiras": "\"partiras\" è la forma tu del futuro semplice di partir, ma qui il soggetto è nous (noi) — persona sbagliata.", "partirai": "\"partirai\" è la forma je del futuro semplice di partir, ma qui il soggetto è nous (noi) — persona sbagliata.", "partirez": "\"partirez\" è la forma vous del futuro semplice di partir, ma qui il soggetto è nous (noi) — persona sbagliata."}},
  "verbo-19": {"promptNative": "Voi ___ (partir = partire) domani mattina.", "explain": "La forma voi di 'partir' (futuro) è 'partirez'.", "wrongNote": "Esercizio di coniugazione: questa frase richiede il futuro semplice (forma vous (voi/formale)) di partir, che è \"partirez\" — \"demain\" (domani) indica il futuro.", "distractorNotes": {"partiront": "\"partiront\" è la forma ils/elles del futuro semplice di partir, ma qui il soggetto è vous (voi/formale) — persona sbagliata.", "partirai": "\"partirai\" è la forma je del futuro semplice di partir, ma qui il soggetto è vous (voi/formale) — persona sbagliata.", "partiras": "\"partiras\" è la forma tu del futuro semplice di partir, ma qui il soggetto è vous (voi/formale) — persona sbagliata."}},
