  "trad-113": {"prompt": "Traduci: 'Cuando las ranas críen pelo.'", "promptNative": "Quando gli asini voleranno.", "explain": "'Cuando las gallinas tengan dientes' è il modo francese di dire mai.", "wrongNote": "Il modo naturale di dirlo è 'quand les poules auront des dents'. 'Cuando las gallinas tengan dientes' è il modo in cui il francese dice mai.", "distractorNotes": {"quand les cochons auront des ailes": "'quand les cochons auront des ailes' — una frase plausibile, ma non l’espressione fissa; il francese dice 'quand les poules auront des dents'.", "quand il neigera en aout": "'quand il neigera en aout' — una frase plausibile, ma non l’espressione fissa; il francese dice 'quand les poules auront des dents'.", "quand les cochons voleront": "'quand les cochons voleront' — una frase plausibile, ma non l’espressione fissa; il francese dice 'quand les poules auront des dents'."}},
  "trad-114": {"prompt": "Traduci: 'Tirar la toalla.'", "promptNative": "Gettare la spugna.", "explain": "Si getta la 'esponja', non l’asciugamano, per arrendersi; 'mettre la main a la pate' è il contrario, darsi da fare.", "wrongNote": "Il modo naturale di dirlo è 'jeter l'eponge'. Per arrendersi si getta la 'esponja', non l’asciugamano; 'mettre la main a la pate' è il contrario, darsi da fare.", "distractorNotes": {"mettre la main a la pate": "'mettre la main a la pate' — la spiegazione la segnala come opzione sbagliata; non è il modo di dire fisso 'jeter l'eponge'.", "lancer la serviette": "'lancer la serviette' — una frase plausibile, ma non l’espressione fissa; il francese dice 'jeter l'eponge'.", "jeter la serviette": "'jeter la serviette' — una frase plausibile, ma non l’espressione fissa; il francese dice 'jeter l'eponge'."}},
  "trad-115": {"prompt": "Traduci: 'Ir de mal en peor.'", "promptNative": "Andare di male in peggio.", "explain": "'De mal en pis' è l’espressione fissa per andare di male in peggio.", "wrongNote": "Il modo naturale di dirlo è 'aller de mal en pis'. 'De mal en pis' è la formula fissa per andare di male in peggio.", "distractorNotes": {"empirer de jour en jour": "'empirer de jour en jour' — una frase plausibile, ma non l’espressione fissa; il francese dice 'aller de mal en pis'.", "aller de mauvais en pire": "'aller de mauvais en pire' — la spiegazione la segnala come opzione sbagliata; non è il modo di dire fisso 'aller de mal en pis'.", "passer du mal au pire": "'passer du mal au pire' — la spiegazione la segnala come opzione sbagliata; non è il modo di dire fisso 'aller de mal en pis'."}},
  "trad-116": {"prompt": "Traduci: 'Estar en el séptimo cielo.'", "promptNative": "Essere al settimo cielo.", "explain": "La gioia piena è essere 'con los angeles' (aux anges); 'avoir le cafard' è il contrario, essere giù di morale.", "wrongNote": "Il modo naturale di dirlo è 'etre aux anges'. La gioia piena è essere 'con los angeles' (aux anges); 'avoir le cafard' è il contrario, essere giù di morale.", "distractorNotes": {"etre sur le nuage neuf": "'etre sur le nuage neuf' — una frase plausibile, ma non l’espressione fissa; il francese dice 'etre aux anges'.", "etre sur le neuvieme nuage": "'etre sur le neuvieme nuage' — una frase plausibile, ma non l’espressione fissa; il francese dice 'etre aux anges'.", "avoir le cafard": "'avoir le cafard' — la spiegazione la segnala come opzione sbagliata; non è il modo di dire fisso 'etre aux anges'."}},
  "trad-117": {"prompt": "Traduci: 'Hacer la vista gorda.'", "promptNative": "Chiudere un occhio.", "explain": "Per ignorare di proposito una mancanza in francese si 'cierran los ojos'.", "wrongNote": "Il modo naturale di dirlo è 'fermer les yeux'. Per ignorare di proposito una mancanza, in francese si 'cierran los ojos'.", "distractorNotes": {"tourner un oeil aveugle": "'tourner un oeil aveugle' — una frase plausibile, ma non l’espressione fissa; il francese dice 'fermer les yeux'.", "detourner un oeil aveugle": "'detourner un oeil aveugle' — una frase plausibile, ma non l’espressione fissa; il francese dice 'fermer les yeux'.", "faire la sourde oreille": "'faire la sourde oreille' — la spiegazione la segnala come opzione sbagliata; non è il modo di dire fisso 'fermer les yeux'."}},
